// ===============================================================================
// DAEMIND SRE - PARSER DE MENSAGEM DO LEAD
// ===============================================================================
const body = $json.body || $json;
const data = body.data || body;
const sender = (data.key?.remoteJid || body.sender || '').toString().replace(/@.*$/, '').replace(/\D/g, '');
const messageText = (data.message?.conversation || data.message?.extendedTextMessage?.text || body.content || body.text || '').trim();
const senderName = (data.pushName || body.sender_name || 'Lead Novo').trim();

return [{
  json: {
    whatsapp: sender,
    nome: senderName,
    mensagem: messageText,
    raw_id: data.key?.id || Date.now().toString()
  }
}];

