// ===============================================================================
// DAEMIND SRE - PARSER E CLASSIFICAÇÃO DE SCORE
// ===============================================================================
const rawContent = $json.choices?.[0]?.message?.content || '{}';
let parsed = {};
try {
  const cleanJson = rawContent.replace(/```json\n?|```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = {
    score: 50,
    interesse_principal: 'Geral',
    tipo_lead: 'DUVIDA_SUPORTE',
    resposta_sugerida: 'Olá! Como posso ajudar você hoje?'
  };
}

return [{
  json: {
    ...parsed,
    lead_score: parseInt(parsed.score || 50, 10),
    whatsapp: $('Sanitizar Dados do Lead').item.json.whatsapp,
    nome: $('Sanitizar Dados do Lead').item.json.nome,
    mensagem_original: $('Sanitizar Dados do Lead').item.json.mensagem
  }
}];

